WITH target_routes AS ( /* Optimization 1: Moving massive IN clause to a CTE to prevent internal engine errors */ SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (122, 123), (123, 122), (123, 141), (124, 122), (122, 124), (124, 134), (122, 71756), (757, 733), (71756, 122), (130, 624), (74820, 74694), (624, 130), (74694, 74820), (130, 309), (122, 216), (124, 123), (134, 122), (130, 575), (124, 462), (123, 124), (462, 124), (122, 71929), (130, 641), (575, 130), (141, 126), (130, 1476), (233, 123), (74661, 122), (641, 130), (248, 134), (126, 141), (122, 995), (130, 361), (995, 122), (71425, 122), (309, 462), (361, 130), (1476, 130), (65976, 130), (122, 95218), (551, 473), (130, 95083), (130, 311), (141, 71929), (624, 124), (313, 551), (95218, 122), (1514, 733), (74701, 79589), (71929, 141), (1290, 733), (123, 504), (122, 78796), (470, 1169), (123, 506), (1382, 130), (733, 1290), (71756, 123), (1437, 733), (624, 361), (70015, 777), (130, 1384), (74701, 93059), (313, 94152), (733, 1437), (361, 624), (70024, 83760), (1384, 130), (122, 923), (130, 65907), (309, 575), (93947, 70014), (575, 309), (1443, 807), (807, 1290), (624, 444), (130, 65859), (833, 777), (646, 130), (1429, 1290), (130, 622), (70015, 833), (122, 65930), (1429, 777), (629, 130), (1290, 1429), (141, 124), (622, 130), (70015, 1290), (777, 1429) ) AS t(s, d) ), viewed AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', date_add('minute', 330, "__time")) AS DATE) AS doi, event_group, event_name, event_value, usertype, mri_session_id viewed_session FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-10 18:30:00' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' AND event_group IN ('great_india_sales', 'India_sale_view_all_loaded', 'India_sale_section_clicked', 'India_sale_section_loaded') -- AND event_name in ('India_sale_section') AND event_value = 'viewed' -- AND sort_label IN ('INDIA_SALE_HANDPICKED') -- and app_version>='81.2' ), clicked AS ( SELECT DISTINCT event_group, event_name, event_value, usertype, mri_session_id clicked_session FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-10 18:30:00' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' AND event_group IN ('great_india_sales', 'India_sale_view_all_loaded', 'India_sale_section_clicked', 'India_sale_section_loaded') -- AND event_name in ('India_sale_section') AND event_value IN ('clicked', 'view_all_clicked') -- AND sort_label IN ('INDIA_SALE_HANDPICKED') -- and app_version>='81.2' ), srp_deduped AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', DATE_ADD('minute', 330, "__time")) AS DATE) AS doi, -- CAST(DATE_TRUNC('hour', DATE_ADD('minute', 330, "__time")) AS TIMESTAMP) AS day_hour, s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, CASE WHEN t.src_id IS NOT NULL AND t.dest_id IS NOT NULL THEN 'Target Route' ELSE 'non-Target Route' END AS route_type FROM "user_interaction"."search_route_details" s LEFT JOIN target_routes t ON s.src_id = t.src_id AND s.dest_id = t.dest_id WHERE s.__time >= TIMESTAMP '2026-01-06 18:30:00' AND s.__time < TIMESTAMP '2026-01-10 18:30:00' -- AND (s.src_id, s.dest_id) IN ((69283, 65782)) -- AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'Android' AND s.country = 'IND' AND s.status = 200 -- AND -- LIMIT 100 -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_lands AS ( SELECT DISTINCT sl.mri_session_id, sl.__time, sr.route_type FROM "user_interaction"."ui_ux_events" sl LEFT JOIN srp_deduped sr ON sl.mri_session_id = sr.mri_session_id WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-10 18:30:00' AND event_name = 'India_sale_load_animation_shown' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' -- LIMIT 20 ), back_click AS ( SELECT "__time" AS back_time, "mri_client_id", "mri_session_id", "event_src" FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-10 18:30:00' AND "header_country" = 'IND' AND "event_src" = 'Android' AND "event_group" = 'sl_click_info' AND "event_name" = 'back button tapped' ), Tuples AS ( SELECT DISTINCT srd.mri_session_id AS srpsession, route_id FROM "user_interaction"."search_route_details" srd WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-10 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND total_ratings >= 3.0 AND os = 'Android' -- AND mri_session_id = 'AMaab40f36-fd15-3802-afa5-c06d2cc7d22b' -- AND (src_id, dest_id) IN ((69283, 65782)) -- AND (src_id, dest_id) IN (SELECT source_id, destination_id FROM top_bharat_sds) AND country = 'IND' ), neon_tickets AS ( SELECT t.mri_session_id, t.tin, t.order_uuid, t.route_id, CASE WHEN (t.mri_session_id, t.route_id) IN (SELECT DISTINCT srpsession, route_id FROM Tuples) THEN 'DBS Tuple' ELSE 'non-DBS Tuple' END AS transacted_tuple_type, DATE(date_of_journey) date_of_journey, st_name AS stname, date_diff('hour', time_of_event, date_of_journey) AS DBD FROM transaction.bus_ticket_events AS t CROSS JOIN UNNEST(t.seat_name) AS u (st_name) WHERE date_of_journey >= TIMESTAMP '2026-01-06 18:30:00' AND date_of_journey < TIMESTAMP '2026-01-10 18:30:00' AND country_code = 'IND' and event_type = 101 AND event_class = 2 ), neon_payment AS ( SELECT DISTINCT order_uuid offer_uuid FROM transaction.bus_payment_events WHERE time_of_event >= timestamp '2026-01-06 18:30:00' -- AND time_of_event < timestamp '2026-01-11 18:30:00' AND event_type = 2 AND payment_system_ref_no LIKE ('%DBIND%')AND country_code = 'IND' ) SELECT v.doi, -- v.event_group, -- v.event_name, v.usertype, sl.route_type, COUNT(DISTINCT v.viewed_session) AS viewed_sessions, COUNT(DISTINCT c.clicked_session) AS interacted_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'clicked' THEN c.clicked_session END) AS clicked_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'clicked' THEN bc.mri_session_id END) AS back_click_sessions_from_first_tuple, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN c.clicked_session END) AS view_all_clicked_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN sl.mri_session_id END) AS dbs_SL_Lands, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN bc.mri_session_id END) AS back_click_sessions_from_view_all, COUNT(DISTINCT nt.mri_session_id) AS overall_interacted_and_converted_sessions, COUNT(DISTINCT CASE WHEN nt.transacted_tuple_type = 'non-DBS Tuple' THEN nt.mri_session_id END) AS interacted_and_converted_non_dbs_tuple_sessions, COUNT(DISTINCT CASE WHEN nt.transacted_tuple_type = 'DBS Tuple' THEN nt.mri_session_id END) AS interacted_and_converted_dbs_tuple_sessions, COUNT(DISTINCT CASE WHEN nt.transacted_tuple_type = 'DBS Tuple' AND np.offer_uuid IS NOT NULL THEN nt.mri_session_id END) AS interacted_and_converted_dbs_seat_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN nt.mri_session_id END) AS overall_view_all_clicked_and_converted_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' AND nt.transacted_tuple_type = 'non-DBS Tuple' THEN nt.mri_session_id END) AS view_all_clicked_and_converted_non_dbs_tuple_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' AND nt.transacted_tuple_type = 'DBS Tuple' THEN nt.mri_session_id END) AS view_all_clicked_and_converted_dbs_tuple_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' AND nt.transacted_tuple_type = 'non-DBS Tuple' AND np.offer_uuid IS NOT NULL THEN nt.mri_session_id END) AS view_all_clicked_and_converted_dbs_seat_sessions, COUNT(DISTINCT CASE WHEN nt.transacted_tuple_type = 'non-DBS Tuple' AND np.offer_uuid IS NOT NULL THEN nt.mri_session_id END) AS converted_dbs_seat_sessions FROM viewed v LEFT JOIN clicked c ON v.viewed_session = c.clicked_session LEFT JOIN Tuples t ON t.srpsession = c.clicked_session LEFT JOIN sl_lands sl ON sl.mri_session_id = c.clicked_session LEFT JOIN back_click bc ON bc.mri_session_id = sl.mri_session_id AND bc.back_time > sl.__time LEFT JOIN neon_tickets nt ON nt.mri_session_id = c.clicked_session LEFT JOIN neon_payment np ON np.offer_uuid = nt.order_uuid GROUP BY 1,2,3 -- ,4 ORDER BY v.doi, v.usertype DESC
